from datetime import datetime

# Chemins des fichiers à analyser
jl02_suivi = "/home/adminjarvis/JARVIS/jl02-docs/SUIVI.md"
jl02_roadmap = "/home/adminjarvis/JARVIS/jl02-docs/ROADMAP.md"
