        return {}

    try:
        with open(filepath, 'r', errors='ignore') as f:
            content = f.read()
    except Exception as e:
        print(f"Erreur lecture {filepath}: {e}")
        return {}

    missions = {}
    lines = content.split('\n')

    for line in lines:
        # Pattern pour détecter les numéros de mission
        pattern = r'^(#+\s*)?(M?\d+[A-Z]?[-./]?)\s*(.*?)(?:\n|$)'
        match = re.match(pattern, line.strip())

        if match:
            marker, number, desc = match.groups()
            if number and 'CONFIRMÉ' in line or 'À FAIRE' in line or 'EN COURS' in line or 'BLOCÉ' in line:
                status_match = re.search(r'(CONFIRMÉ|À FAIRE|EN COURS|BLOCÉ|ANNULÉ)', line)
                if status_match:
                    status = status_match.group(1)
                    desc_clean = desc.strip().replace('*', '').strip()
                    missions[number] = {
                        'description': desc_clean[:60],
                        'status': status,
                        'line_num': len([l for l in content.split('\n') if l != line])
                    }

    # Pattern alternatif pour liste numérotée
    pattern2 = r'^(\d+\.)\s+(M?\d+[A-Z]?[-./]?\s+)?(.*)'
    lines_content = content.split('\n')

    for i, line in enumerate(lines_content):
        match = re.match(pattern2, line.strip())
        if match:
            num_item = match.group(1)
            mission_part = match.group(2)
            text = match.group(3)

            # Chercher un numéro de mission dans le texte
            mission_match = re.search(r'(M?\d+[A-Z]?)', text)
            if mission_match:
                m_num = mission_match.group(1)
                status_str = ''
                for status in ['CONFIRMÉ', 'À FAIRE', 'EN COURS', 'BLOCÉ', 'ANNULÉ']:
                    if status in line.upper():
                        status_str = status
                        break

                if m_num not in missions and text.strip()[:40]:
                    missions[m_num] = {
                        'description': text.strip()[:60],
                        'status': status_str if status_str else 'NON DÉFINI',
                        'line_num': i + 1
                    }

    return missions

# Extraire les missions des deux sources
jl02_missions_suivi = extract_missions(jl02_suivi, "JL02-SUIVI")
jl02_missions_roadmap = extract_missions(jl02_roadmap, "JL02-ROADMAP")
m00_missions_suivi = extract_missions(m00_suivi, "M00-SUIVI")
m00_missions_roadmap = extract_missions(m00_roadmap, "M00-ROADMAP")

# Combiner les missions par source
jl02_all = {}
for key, val in jl02_missions_suivi.items():
    if key not in jl02_all:
        jl02_all[key] = {'desc': val['description'], 'status': val['status'], 'source': 'SUIVI'}
    else:
        jl02_all[key]['details'] = val.get('details', '')

for key, val in jl02_missions_roadmap.items():
    if key not in jl02_all:
        jl02_all[key] = {'desc': val['description'], 'status': val['status'], 'source': 'ROADMAP'}
    else:
        jl02_all[key]['roadmap'] = True

m00_all = {}
for key, val in m00_missions_suivi.items():
    if key not in m00_all:
        m00_all[key] = {'desc': val['description'], 'status': val['status'], 'source': 'SUIVI'}

for key, val in m00_missions_roadmap.items():
    if key not in m00_all:
        m00_all[key] = {'desc': val['description'], 'status': val['status'], 'source': 'ROADMAP'}
    else:
        m00_all[key]['roadmap'] = True

# Générer la matrice de comparaison
output_lines = [
    "# CONCORDANCE JARVIS - Matrice de comparaison",
    "## Bilan des différences entre JL02-DOCS et MISSION00",
    "",
    "| Numéro | Fonction | État Ancien (JL02) | État Récent (M00) | Chemin Ancien | Chemin Récent | Correction/Statut |",
    "|--------|----------|-------------------|------------------|---------------|---------------|-------------------|"
]

# Missions spécifiques à surveiller
prioritaires = ['13D', '14A', '14B', '11', '11-Agentic', '11B', '15A', '15B', 'Dell1', 'Dell2']

all_mission_keys = set(jl02_all.keys()) | set(m00_all.keys())

for m_key in sorted(all_mission_keys):
    jl02_data = jl02_all.get(m_key, {})
    m00_data = m00_all.get(m_key, {})

    func = (jl02_data.get('desc', '') or m00_data.get('desc', '') or f"Mission {m_key}")[:50]
    etat_ancien = jl02_data.get('status', '-')
    etat_recent = m00_data.get('status', '-')

    # Déterminer statut de correction
    if etat_ancien == etat_recent and etat_recent != '-':
        statut = "CONFIRMÉ"
    elif etat_recent in ['CONFIRMÉ', 'EN COURS']:
        statut = f"MIS À JOUR ({etat_recent})"
    elif etat_ancien != '-' and etat_recent == '-':
        statut = "NON MIGRÉ"
    else:
        statut = "À CONFIRMER"

    ligne = f"| {m_key} | {func} | {etat_ancien} | {etat_recent} | jl02-docs | mission00 | {statut} |"
    output_lines.append(ligne)

# Ajouter un bilan des différences notables
output_lines.extend([
    "",
    "## Bilan Exécutif",
    "- Missions confirmées: missions avec statut identique dans JL02 et M00",
    "- Missions à migrer: missions présentes dans JL02 mais absentes de M00",
    "- Missions nouvelles: missions apparaissant uniquement dans M00",
    "",
    "## Notes Spécifiques",
    f"- Date génération: {datetime.now().strftime('%Y-%m-%d %H:%M')}",
    f"- Total missions analysées: {len(all_mission_keys)}",
    ""
])

# Écrire le fichier
output_path = "/var/lib/jarvis/projects/mission00/CONCORDANCE-JARVIS.md"
try:
    with open(output_path, 'w') as f:
        content = '\n'.join(output_lines)
        f.write(content)
    print(f"Fichier écrit avec succès: {output_path}")
    print(f"Lignes écrites: {len(output_lines)}")
    print(f"Taille caractères: {len(content)}")
except Exception as e:
    print(f"Erreur écriture: {e}")

